  timeoutMs: number;
  retries: number;
}

export class ABTestsExperimentsService {
  constructor(private config: ConfigOptions) {}

  public async executeTask<T>(taskFn: () => Promise<T>): Promise<T> {
    let attempt = 0;
    while (attempt < this.config.retries) {
      try {
        return await this.withTimeout(taskFn(), this.config.timeoutMs);
      } catch (err) {
        attempt++;
        if (attempt >= this.config.retries) throw err;
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 100)); // Exponential backoff
      }
    }
    throw new Error("Exhausted retries");
  }

  private withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) => setTimeout(() => reject(new Error("Operation timed out")), ms))
    ]);
  }
}

