// Production Architecture Pattern: Version Control Systems
interface ServiceNode {
  id: string;
  weight: number;
  isHealthy: boolean;
}

export class DistributedCoordinator {
  private nodes: Map<string, ServiceNode> = new Map();
  private replicationFactor = 3;

  constructor(private clusterName: string) {}

  // Distribute request or partition key across healthy nodes
  public routeRequest(partitionKey: string): ServiceNode | null {
    const healthyNodes = Array.from(this.nodes.values()).filter(n => n.isHealthy);
    if (healthyNodes.length === 0) throw new Error("Cluster unavailable (Circuit Breaker OPEN)");

    // Hash ring partition lookup (Consistent Hashing)
    const hash = this.hashString(partitionKey);
    const index = Math.abs(hash) % healthyNodes.length;
    return healthyNodes[index];
  }

  private hashString(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash << 5) - hash + str.charCodeAt(i);
      hash |= 0; // Convert to 32bit integer
    }
    return hash;
  }
}

