// Production Architecture Pattern: Filesystems
interface ServiceNode {
  id: string;
  weight: number;
  isHealthy: boolean;
}

export class DistributedCoordinator {
  private nodes: Map<string, ServiceNode> = new Map();
  private replicationFactor = 3;

  constructor(private clusterName: string) {}

  // Distribute request or partition key across healthy nodes
  public routeRequest(partitionKey: string): ServiceNode | null {
    const healthyNodes = Array.from(this.nodes.values()).filter(n => n.isHealthy);
    if (healthyNodes.length === 0) throw new Error("Cluster unavailable (Circuit Breaker OPEN)");

    // Hash ring partition lookup (Consistent Hashing)
    const hash = this.hashString(partitionKey);
    const index = Math.abs(hash) % healthyNodes.length;
    return healthyNodes[index];
  }

  private hashString(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = (hash << 5) - hash + str.charCodeAt(i);
      hash |= 0; // Convert to 32bit integer
    }
    return hash;
  }
}

// Production Implementation: Swap
export interface ConfigOptions {
  enabled: boolean;
  timeoutMs: number;
  retries: number;
}

export class SwapService {
  constructor(private config: ConfigOptions) {}

  public async executeTask<T>(taskFn: () => Promise<T>): Promise<T> {
    let attempt = 0;
    while (attempt < this.config.retries) {
      try {
        return await this.withTimeout(taskFn(), this.config.timeoutMs);
      } catch (err) {
        attempt++;
        if (attempt >= this.config.retries) throw err;
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 100)); // Exponential backoff
      }
    }
    throw new Error("Exhausted retries");
  }

  private withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) => setTimeout(() => reject(new Error("Operation timed out")), ms))
    ]);
  }
}

