import { Request, Response, NextFunction } from 'express';

// Idempotent Request Handler & Middleware
export const handleGarbageCollection = async (
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> => {
  const idempotencyKey = req.headers['x-idempotency-key'] as string;
  if (!idempotencyKey) {
    res.status(400).json({ error: "Idempotency key required for safe execution" });
    return;
  }

  try {
    // 1. Check if operation already succeeded in Redis
    const cachedResult = await redisClient.get(`idemp:${idempotencyKey}`);
    if (cachedResult) {
      res.status(200).json(JSON.parse(cachedResult));
      return;
    }

    // 2. Perform business logic with transaction
    const data = await executeDomainService(req.body);

    // 3. Cache idempotent result for 24h
    await redisClient.setex(`idemp:${idempotencyKey}`, 86400, JSON.stringify(data));
    res.status(200).json(data);
  } catch (err) {
    next(err);
  }
};

